<?php

declare(strict_types=1);

use Jira2Redmine\Workflows\WorkflowScripts;
use PHPUnit\Framework\TestCase;

final class WorkflowScriptsTest extends TestCase
{
    public function testTheScriptAssignsTheCurrentUserOnlyOnThatTransition(): void
    {
        $script = WorkflowScripts::assignToCurrentUser(6, 5, [2, 1, 2], ['Close']);

        self::assertSame(implode("\n", [
            '# Jira post function "assign to the current user" (Close), generated by tools/workflow_proposal.php',
            'if tracker_id == 6 && status_id == 5 && (new_record? || status_id_changed?) &&',
            '   [1, 2].include?(new_record? ? 0 : status_id_was.to_i) &&',
            '   User.current.logged? && assignable_users.include?(User.current)',
            '  self.assigned_to = User.current',
            'end',
        ]), $script);
        self::assertSame('j2r: assign to the current user, tracker #6, to status #5', WorkflowScripts::name(6, 5));
        self::assertStringStartsWith(WorkflowScripts::NAME_PREFIX, WorkflowScripts::name(1, 1));
    }
}
